import csv, os
T1 = ("Durante años se creyó que dormir era tiempo perdido para el estudiante que se prepara para un examen. "
      "Sin embargo, diversas investigaciones muestran que, mientras dormimos, el cerebro reorganiza lo aprendido durante el día: "
      "fortalece las conexiones útiles y descarta información irrelevante. Por ello, quien sacrifica horas de sueño para estudiar "
      "más suele recordar menos al día siguiente. Esto no significa que basta con dormir para aprender; el sueño consolida lo que "
      "se estudió con atención, pero no puede fijar lo que nunca se comprendió. La recomendación, entonces, no es estudiar menos, "
      "sino distribuir el estudio en varios días y proteger el descanso, especialmente la noche previa a la evaluación.")
T2 = ("Muchas personas piensan que reciclar es la solución principal al problema de los residuos. No obstante, el reciclaje es "
      "solo la última de varias estrategias. Antes de reciclar, conviene reducir lo que consumimos y reutilizar lo que ya tenemos, "
      "pues todo proceso de reciclaje requiere energía, transporte y agua. Una botella que se reutiliza diez veces evita fabricar "
      "nueve botellas nuevas; una botella reciclada, en cambio, debe ser recolectada, limpiada, triturada y fundida. Por eso, los "
      "especialistas sostienen que una ciudad que recicla mucho pero consume sin control no es necesariamente una ciudad sostenible.")
Q = []
def q(area, curso, tema, dif, enun, ops, resp, sol, texto=""):
    Q.append(dict(area=area, curso=curso, tema=tema, dificultad=dif, texto=texto, enunciado=enun,
                  A=ops[0], B=ops[1], C=ops[2], D=ops[3], E=ops[4], respuesta=resp, solucion=sol))
RM, MB, CL, RD = "Razonamiento Matemático", "Matemática Básica", "Comprensión Lectora", "Redacción"
q(RM, "Razonamiento Matemático", "Sucesiones", 1, "Halla el término que sigue: 3; 7; 15; 31; ...", ["63", "64", "65", "72", "127"], "A", "Cada término es el anterior por 2 más 1: 31 × 2 + 1 = 63.")
q(RM, "Razonamiento Matemático", "Sucesiones", 2, "Halla el término que sigue: 2; 5; 10; 17; 26; ...", ["26", "31", "35", "36", "37"], "E", "Los términos son n² + 1 para n = 1, 2, 3...; el sexto es 6² + 1 = 37.")
q(RM, "Razonamiento Matemático", "Magnitudes proporcionales", 1, "Tres obreros hacen una obra en 12 días. Trabajando al mismo ritmo, ¿en cuántos días harían la misma obra 6 obreros?", ["3", "4", "6", "8", "24"], "C", "Obreros y días son inversamente proporcionales: 3 × 12 = 6 × d, entonces d = 6.")
q(RM, "Razonamiento Matemático", "Porcentajes", 2, "El precio de un producto sube 20 % y luego baja 20 %. Respecto del precio inicial, el precio final:", ["no varía", "aumenta 4 %", "disminuye 4 %", "disminuye 2 %", "aumenta 2 %"], "C", "1,20 × 0,80 = 0,96: el precio final es 96 % del inicial, es decir, disminuye 4 %.")
q(RM, "Razonamiento Matemático", "Edades", 2, "Hace 5 años, la edad de Ana era el doble de la de Beto. Dentro de 5 años, sus edades sumarán 50 años. ¿Qué edad tiene Ana hoy?", ["20", "22", "25", "28", "30"], "C", "A − 5 = 2(B − 5) da A = 2B − 5. Además A + B + 10 = 50, así que A + B = 40. Entonces 3B − 5 = 40, B = 15 y A = 25.")
q(RM, "Razonamiento Matemático", "Fracciones (trabajo)", 2, "El caño A llena un tanque en 6 horas y el caño B lo llena en 3 horas. Si se abren ambos a la vez con el tanque vacío, ¿en cuántas horas se llena?", ["1,5", "2", "2,5", "3", "4,5"], "B", "En una hora llenan 1/6 + 1/3 = 1/2 del tanque; el tanque completo se llena en 2 horas.")
q(RM, "Razonamiento Matemático", "Probabilidades", 2, "Se lanzan dos dados comunes. ¿Cuál es la probabilidad de que la suma de los resultados sea 7?", ["1/12", "1/9", "1/6", "7/36", "1/3"], "C", "Hay 36 resultados posibles y 6 suman 7: (1,6), (2,5), (3,4), (4,3), (5,2), (6,1). Probabilidad 6/36 = 1/6.")
q(RM, "Razonamiento Matemático", "Análisis combinatorio", 1, "¿De cuántas maneras distintas se pueden ordenar todas las letras de la palabra ASTRO?", ["24", "60", "100", "110", "120"], "E", "Son 5 letras distintas: 5! = 120.")
q(RM, "Razonamiento Matemático", "Promedios", 2, "El promedio de cinco números es 18. Si se retira uno de ellos, el promedio de los cuatro restantes es 17. ¿Qué número se retiró?", ["22", "24", "26", "34", "68"], "A", "Suma de los cinco: 5 × 18 = 90. Suma de los cuatro: 4 × 17 = 68. Número retirado: 90 − 68 = 22.")
q(RM, "Razonamiento Matemático", "Operadores", 2, "Se define a ✱ b = 2a − b. Calcula (3 ✱ 1) ✱ 4.", ["2", "4", "5", "6", "8"], "D", "3 ✱ 1 = 6 − 1 = 5. Luego 5 ✱ 4 = 10 − 4 = 6.")
q(RM, "Razonamiento Matemático", "Conjuntos", 2, "En un aula de 40 alumnos, 25 estudian Matemática, 20 estudian Física y 8 no estudian ninguno de esos cursos. ¿Cuántos estudian ambos cursos?", ["5", "8", "10", "12", "13"], "E", "Estudian al menos uno: 40 − 8 = 32. Ambos: 25 + 20 − 32 = 13.")
q(RM, "Razonamiento Matemático", "Móviles", 1, "Un auto recorre 180 km en 2 horas y 30 minutos. ¿Cuál es su velocidad media?", ["60 km/h", "72 km/h", "75 km/h", "80 km/h", "90 km/h"], "B", "2 h 30 min = 2,5 h. Velocidad = 180 ÷ 2,5 = 72 km/h.")
q(RM, "Razonamiento Matemático", "Lógica", 3, "Si todos los estudiantes de ASTROS son puntuales y algunos puntuales son deportistas, entonces es necesariamente cierto que:", ["algunos estudiantes de ASTROS son deportistas", "ningún estudiante de ASTROS es deportista", "todos los puntuales son estudiantes de ASTROS", "algunos puntuales son estudiantes de ASTROS", "todos los deportistas son puntuales"], "D", "Si todos los estudiantes de ASTROS son puntuales (y hay al menos uno), algunos puntuales son de ASTROS. Las demás no se pueden asegurar: los deportistas puntuales podrían no ser de ASTROS.")
q(MB, "Álgebra", "Ecuaciones lineales", 1, "Resuelve: 2x + 3 = 5x − 9", ["2", "3", "4", "6", "12"], "C", "3 + 9 = 5x − 2x, entonces 12 = 3x y x = 4.")
q(MB, "Aritmética", "Porcentajes", 1, "¿Cuánto es el 30 % del 40 % de 500?", ["60", "70", "120", "150", "200"], "A", "40 % de 500 = 200; 30 % de 200 = 60.")
q(MB, "Aritmética", "Descuentos", 1, "Luego de un descuento del 20 %, un libro cuesta S/ 80. ¿Cuál era su precio original?", ["S/ 96", "S/ 100", "S/ 104", "S/ 110", "S/ 120"], "B", "80 es el 80 % del precio original: P = 80 ÷ 0,8 = 100.")
q(MB, "Geometría", "Áreas", 1, "Un rectángulo tiene perímetro 30 cm y su largo es el doble de su ancho. ¿Cuál es su área?", ["25 cm²", "45 cm²", "50 cm²", "60 cm²", "72 cm²"], "C", "2(2a + a) = 30 da a = 5 y largo 10. Área = 5 × 10 = 50 cm².")
q(MB, "Álgebra", "Leyes de exponentes", 1, "Simplifica: 2¹⁰ ÷ 2⁷", ["2", "4", "6", "7", "8"], "E", "2¹⁰ ÷ 2⁷ = 2³ = 8.")
q(MB, "Álgebra", "Sistemas de ecuaciones", 2, "Si x + y = 10 y x − y = 4, ¿cuánto vale x · y?", ["16", "21", "24", "25", "30"], "B", "Sumando: 2x = 14, x = 7; luego y = 3. x · y = 21.")
q(MB, "Álgebra", "Productos notables", 2, "Si a + b = 7 y a · b = 10, ¿cuánto vale a² + b²?", ["29", "39", "49", "59", "69"], "A", "a² + b² = (a + b)² − 2ab = 49 − 20 = 29.")
q(MB, "Geometría", "Teorema de Pitágoras", 1, "Los catetos de un triángulo rectángulo miden 6 cm y 8 cm. ¿Cuánto mide la hipotenusa?", ["9 cm", "10 cm", "12 cm", "14 cm", "48 cm"], "B", "h² = 6² + 8² = 36 + 64 = 100, h = 10 cm.")
q(CL, "Comprensión Lectora", "Idea principal", 1, "¿Cuál es la idea principal del texto?", ["Dormir es más importante que estudiar antes de un examen.", "El sueño ayuda a consolidar lo aprendido, por lo que conviene distribuir el estudio y proteger el descanso.", "El cerebro descarta toda la información que se estudia de noche.", "Los estudiantes que duermen poco tienen más tiempo para aprender.", "Basta con dormir bien para aprender cualquier tema."], "B", "El texto explica que el sueño consolida lo aprendido y concluye recomendando distribuir el estudio y proteger el descanso. A y E exageran; C y D contradicen el texto.", T1)
q(CL, "Comprensión Lectora", "Inferencia", 2, "Del texto se infiere que un estudiante que no entendió un tema:", ["lo recordará si duerme ocho horas.", "debe dejar de dormir para repasarlo.", "tiene que estudiarlo únicamente la noche anterior al examen.", "olvidará también los temas que sí comprendió.", "no lo fijará solo durmiendo; primero necesita comprenderlo."], "E", "El texto dice que el sueño 'no puede fijar lo que nunca se comprendió'.", T1)
q(CL, "Comprensión Lectora", "Incompatibilidad", 2, "Es incompatible con lo que sostiene el autor afirmar que:", ["el sueño reorganiza lo aprendido durante el día.", "conviene estudiar en varios días.", "trasnochar estudiando garantiza un mejor rendimiento al día siguiente.", "el descanso es importante la noche previa a la evaluación.", "el cerebro descarta información irrelevante mientras dormimos."], "C", "El autor afirma que quien sacrifica horas de sueño 'suele recordar menos al día siguiente'.", T1)
q(CL, "Comprensión Lectora", "Tema central", 1, "¿Cuál es el tema central del texto?", ["La historia del reciclaje de botellas.", "El reciclaje como una estrategia más, posterior a reducir y reutilizar.", "El consumo de agua en las ciudades.", "Las ventajas de fabricar botellas nuevas.", "La prohibición de reciclar en las ciudades."], "B", "El texto sostiene que el reciclaje es 'solo la última de varias estrategias', después de reducir y reutilizar.", T2)
q(CL, "Comprensión Lectora", "Sentido contextual", 2, "En el texto, la palabra SOSTENIBLE se refiere a una ciudad que:", ["puede mantenerse en el tiempo sin agotar sus recursos.", "tiene muchas plantas de reciclaje.", "fabrica sus propias botellas.", "consume más de lo que produce.", "transporta sus residuos a otras ciudades."], "A", "El texto opone 'sostenible' a 'consumir sin control': se refiere a no agotar recursos en el tiempo.", T2)
q(CL, "Comprensión Lectora", "Inferencia", 3, "Según el texto, reutilizar una botella es preferible a reciclarla porque:", ["las botellas recicladas no sirven.", "reciclar no requiere energía.", "una botella reciclada dura diez veces más.", "reutilizar está prohibido en muchas ciudades.", "evita los costos de energía, transporte y agua que exige reciclar."], "E", "El texto indica que reciclar requiere energía, transporte y agua, mientras que reutilizar evita fabricar botellas nuevas.", T2)
q(RD, "Redacción", "Conectores", 1, "Elige el conector adecuado: «Estudió durante varios meses; ______, no alcanzó el puntaje mínimo.»", ["por lo tanto", "sin embargo", "es decir", "además", "por ejemplo"], "B", "Hay una relación de oposición entre estudiar mucho y no alcanzar el puntaje: 'sin embargo'.")
q(RD, "Redacción", "Puntuación", 2, "¿Qué oración está correctamente puntuada?", ["María, estudia en la PUCP.", "Los alumnos, que llegaron tarde no rindieron el examen.", "Lima, la capital del Perú, tiene muchas universidades.", "Compré: lápices, cuadernos y reglas.", "Sin embargo los resultados, fueron buenos."], "C", "La aposición explicativa 'la capital del Perú' va entre comas. En A y E sobra la coma entre sujeto y verbo o está mal ubicada; en B falta cerrar el inciso; en D no van dos puntos tras el verbo.")
q(RD, "Redacción", "Tildación", 2, "¿En qué oración la tilde está bien empleada?", ["Él no sabe donde queda la biblioteca.", "¿Cuándo empieza el examen?", "Te lo dí ayer.", "El examen fué difícil.", "Quiero que me digas porqué no viniste."], "B", "'Cuándo' interrogativo lleva tilde. 'Dónde' debía tildarse en A (interrogativa indirecta); 'di' y 'fue' son monosílabos sin tilde; en E corresponde 'por qué'.")
q(RD, "Redacción", "Precisión léxica", 1, "Reemplaza el verbo subrayado por uno más preciso: «El ministro DIJO su renuncia ayer.»", ["habló", "presentó", "hizo", "contó", "puso"], "B", "Una renuncia se 'presenta'. Los demás verbos son imprecisos o incorrectos en este contexto.")
q(RD, "Redacción", "Eliminación de oraciones", 2, "Señala la oración que debe eliminarse por no corresponder al tema: (I) El café es una de las bebidas más consumidas del mundo. (II) Su cultivo se concentra en zonas tropicales. (III) El Perú es uno de los principales exportadores de café orgánico. (IV) El té verde tiene antioxidantes. (V) La cosecha de café da trabajo a miles de familias.", ["I", "II", "III", "IV", "V"], "D", "Todas las oraciones tratan del café, excepto la IV, que habla del té verde.")
q(RD, "Redacción", "Plan de redacción", 3, "Ordena las ideas: (1) Finalmente, revisa tus errores para no repetirlos. (2) Primero, identifica los temas que más te cuestan. (3) Luego, practica con preguntas de exámenes anteriores. (4) Cómo preparar un simulacro eficaz. (5) Después, toma un simulacro cronometrado.", ["4-2-3-5-1", "2-3-5-1-4", "4-3-2-5-1", "4-2-5-3-1", "2-4-3-1-5"], "A", "El título (4) va primero y luego la secuencia marcada por los conectores: primero (2), luego (3), después (5), finalmente (1).")
for i, r in enumerate(Q, 1):
    r.update(id=f"PUCP-{i:03d}", universidad="PUCP", examen="Primera Opción / Evaluación del Talento",
             fuente="Original ASTROS (estilo PUCP)", estado="Revisado por Claude", tiempo_seg=90 if r["area"] in (RM, MB) else 75)
COLS = ["id", "universidad", "examen", "area", "curso", "tema", "dificultad", "texto", "enunciado", "A", "B", "C", "D", "E", "respuesta", "solucion", "tiempo_seg", "fuente", "estado"]
with open(os.path.join(os.path.dirname(os.path.dirname(os.path.abspath(__file__))), "preguntas.csv"), "w", newline="", encoding="utf-8") as f:
    w = csv.DictWriter(f, fieldnames=COLS); w.writeheader(); w.writerows(Q)
print(len(Q))
